/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * Our own minimal runtime definitions. The firmware is built with
 * -nostdinc, so nothing here comes from a C library.
 */

#ifndef SB_H
#define SB_H

typedef unsigned char u8;
typedef unsigned short u16;
typedef unsigned int u32;

_Static_assert(sizeof(u16) == 2, "u16 is 16 bits");
_Static_assert(sizeof(u32) == 4, "u32 is 32 bits");

/* The beacon: words at the start of main RAM (firmware/app.ld) that
 * fwtest reads with --ram and --watchdog (HW-26). Tests depend on this
 * layout; change it only together with tests/fw/ and tools/fw-suite.py.
 * The first four words keep M0d's meaning, which tools/perf.py also reads
 * from older records' images. fwtest can take a capture in the middle of
 * the tick handler (docs/HARNESS.md, "Time"), so the handler writes the
 * heartbeat twice, first (beats, ticks) then (beats_b, ticks_b), between
 * two increments of seq: a capture can split at most one copy, so at
 * least one is always consistent, and both are when seq is even. */
struct sb_beacon {
    u32 marker;   /* SB_MARKER once main runs and startup checked out */
    u32 beats;    /* heartbeat: whole milliseconds of the time base */
    u32 ticks;    /* time base ticks since main started it, at the last tick */
    u32 period;   /* ticks per heartbeat, for the tests to read */
    u32 seq;      /* odd while the tick handler is updating the heartbeat */
    u32 beats_b;  /* the second copy of beats and ticks, written after them */
    u32 ticks_b;
    u32 tick_count;     /* tick interrupts taken */
    u32 interval_min;   /* shortest time base interval between two ticks */
    u32 interval_max;   /* longest */
    u32 wakes;          /* times main's idle wait returned (since M2 stored
                         * once a second, with wakes_ticks) */
    u32 clock;          /* sb_clock_measure: time base ticks per SB_CLOCK_CYCLES */
    u32 halt_reason;    /* SB_HALT_*, 0 while running */
    u32 halt_source;    /* the interrupt source, or which stack's guard */
    u32 halt_reti;      /* where the interrupt came in (reti), if any */
    /* Since M2: the screen (docs/DESIGN-NOTES.md, M2). Times are in time
     * base ticks (24 per microsecond). */
    u32 screen;         /* SB_SCREEN_*: what the panel shows */
    u32 loop_ticks;     /* tick_count when main's idle loop began */
    u32 frames;         /* whole frames sent to the panel */
    u32 frame_ticks;    /* the last whole frame: window set to last byte sent */
    u32 render_ticks;   /* drawing the test screen into the frame buffer */
    u32 beat_ticks;     /* the last heartbeat update: drawn and its rows sent */
    u32 shown;          /* the heartbeat's seconds on the screen */
    u32 chunks;         /* DMA transfers to the panel */
    u32 wakes_ticks;    /* tick_count when main last stored wakes */
};

/* What the screen shows (sb_beacon.screen), in order. */
#define SB_SCREEN_NONE    0u
#define SB_SCREEN_PATTERN 1u  /* the address pattern (screen.c) */
#define SB_SCREEN_TEST    2u  /* the test screen with the heartbeat */

#define SB_MARKER     0x44304253u  /* "SB0D" in memory order */
#define SB_MARKER_BAD 0x21444142u  /* "BAD!": startup left data wrong */

/* The stack fill pattern, which is also each stack's guard (crt0.S). */
#define SB_STACK_FILL 0x4B415453u  /* "STAK" */

/* Why the firmware halted (the beacon, and the console line). */
#define SB_HALT_STRAY 1u  /* an interrupt with no handler */
#define SB_HALT_FAULT 2u  /* a CPU exception source (0 to 2) */
#define SB_HALT_STACK 3u  /* a stack's guard word was overwritten */

extern volatile struct sb_beacon sb_beacon;

int main(void) __attribute__((noreturn));

/* main.c */
void sb_console_write(const char *text, u32 words);
void sb_tick(void) __attribute__((interrupt("")));

void sb_wait_ms(u32 ms);

/* irq.c */
void sb_irq_init(void);
void sb_irq_enable(u32 source, void (*handler)(void), u32 priority);
void sb_irq_on(void);
void sb_halt(u32 reason, u32 source, u32 reti) __attribute__((noreturn));

/* The time base's count (HW-13), for timing. */
u32 sb_now(void);

/* lcd.c: the panel (HW-27 to HW-32). Rows are whole rows of the frame
 * buffer, sent from it as they are. */
void lcd_init(void);
void lcd_command(u8 command, const u8 *params, u32 count);
void lcd_send_rows(u32 first, u32 rows);
void lcd_wait(void);
void lcd_spi_done(void) __attribute__((interrupt("")));
#define LCD_DISPON 0x29u

/* gfx.c: drawing into the frame buffer. Colours are RGB565 (HW-27). */
#define SCREEN_W 240u
#define SCREEN_H 240u
#define RGB565(r5, g6, b5) ((u32)(r5) << 11 | (u32)(g6) << 5 | (u32)(b5))
extern u16 sb_fb[SCREEN_W * SCREEN_H];
void gfx_fill(u32 x, u32 y, u32 w, u32 h, u32 colour);
void gfx_frame(u32 x, u32 y, u32 w, u32 h, u32 colour);
void gfx_line(int x0, int y0, int x1, int y1, u32 colour);
void gfx_pixel(u32 x, u32 y, u32 colour);
u32 gfx_text(u32 x, u32 y, const char *text, u32 fg, u32 bg, u32 scale);
void gfx_glyph(u32 x, u32 y, u32 c, u32 fg, u32 bg, u32 scale);

/* font.c: our own font, 5 x 8 in a 6 x 8 cell, printable ASCII. */
#define FONT_W 5u
#define FONT_H 8u
#define FONT_CELL 6u
#define FONT_FIRST 32u
#define FONT_LAST 126u
extern const u8 font_glyphs[FONT_LAST - FONT_FIRST + 1][FONT_H];

/* screen.c */
void screen_pattern(void);
void screen_test(void);
void screen_beat(void);

/* crt0.S */
u32 sb_clock_measure(volatile u32 *count);
#define SB_CLOCK_CYCLES 2402u  /* instructions between its two reads */

/* Test builds only (firmware/src/probe.c). */
#if defined(SB_PROBE_SLOW)
void sb_probe_slow(void);
#endif
#if defined(SB_PROBE_BIG)
void sb_probe_big(void);
#endif
#if defined(SB_PROBE_STACK)
void sb_probe_stack(void);
#endif
#if defined(SB_TEST_FAULT)
void sb_test_fault(void);
#endif
#if defined(SB_TEST_STRAY)
void sb_test_stray(void);
#endif
#if defined(SB_TEST_BADINSN)
void sb_test_badinsn(void);
#endif
#if defined(SB_TEST_FLOOD)
void sb_test_flood(void) __attribute__((noreturn));
#endif

#endif
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * The firmware's main: check that startup gave C its memory, write the
 * marker, measure the core clock, start the 1 ms tick interrupt that
 * keeps the heartbeat (M1), bring up the screen and show the address
 * pattern, then the test screen (M2), and idle between ticks, putting the
 * heartbeat on the screen once a second.
 */

#include "sb.h"
#include "WL82.h"

/* HW-25: in fwtest each word written here is appended to the console. The
 * SDK declares DBG_MSG read-only (Q-5), so it is written through our own
 * pointer rather than the SDK's struct. */
#define DBG_MSG (*(volatile u32 *)0x01EEE244u)

/* HW-13: TIMER4 counts 24 MHz once CON bit 0 is set: the time base. */
#define TIMER4_RUN   0x1u
#define TICKS_PER_MS 24000u

/* HW-16: TIMER0 runs with CON bits 0-1 non-zero, bits 4-7 = 2 divide the
 * 24 MHz clock by 16, and it interrupts on reaching PRD: 1500 counts of
 * 1.5 MHz is 1 ms. Writing CON with bit 14 acknowledges it. */
#define TICK_CON     0x21u
#define TICK_ACK     (1u << 14)
#define TICK_PRD     1500u

/* HW-19, HW-20: the sources main enables, and their priorities. The tick
 * is above SPI1's, so a tick waits at most for one short SPI1 handler
 * (DESIGN-NOTES.md, M2). */
#define SRC_TIMER0   4u
#define SRC_SPI1     16u
#define PRIO_TICK    1u
#define PRIO_SPI1    0u

/* When the test screen replaces the address pattern, in beats. */
#define TEST_SCREEN_MS 500u
#define BEATS_PER_SECOND 1000u

extern u32 __stack_limit[], __irq_stack_top[];

volatile struct sb_beacon sb_beacon __attribute__((section(".beacon")));

/* One of each kind of C data, for main to check that sb_start copied and
 * cleared them. */
static volatile u32 data_probe = 0x5EED0001u;
static volatile u32 bss_probe;

/* The heartbeat's state, kept by sb_tick: the time base when main started
 * it, the ticks counted into beats so far, the time base at the last
 * tick. */
static u32 tb_start, tb_done, tb_last;

u32 sb_now(void)
{
    return JL_TIMER4->CNT;
}

/* Waits at least ms milliseconds on the heartbeat, idling between ticks:
 * one beat more, since the first may be nearly over. */
void sb_wait_ms(u32 ms)
{
    u32 until = sb_beacon.beats + ms + 1;

    while ((int)(sb_beacon.beats - until) < 0)
        __asm__ volatile("idle");
}

void sb_console_write(const char *text, u32 words)
{
    while (words--) {
        const u8 *b = (const u8 *)text;
        DBG_MSG = (u32)b[0] | (u32)b[1] << 8 | (u32)b[2] << 16 | (u32)b[3] << 24;
        text += 4;
    }
}

/* The tick. The heartbeat counts whole milliseconds of the time base, not
 * ticks, so it stays exact whatever the tick's own period does (our fwtest
 * runs measure TIMER0's 1 ms as 24 000.7 time base ticks: DESIGN-NOTES.md,
 * M1); the ticks and their intervals are counted on the side. */
void sb_tick(void)
{
    u32 now = JL_TIMER4->CNT - tb_start;
    u32 n = sb_beacon.tick_count, beats;

    JL_TIMER0->CON = TICK_CON | TICK_ACK;
    sb_beacon.seq++;
    if (n) {
        u32 d = now - tb_last;
        if (n == 1 || d < sb_beacon.interval_min)
            sb_beacon.interval_min = d;
        if (d > sb_beacon.interval_max)
            sb_beacon.interval_max = d;
    }
    tb_last = now;
    sb_beacon.tick_count = n + 1;
    /* Every whole millisecond that has passed, so a late tick still leaves
     * the right count. Unsigned differences stay right across a wrap. */
    beats = sb_beacon.beats;
    while (now - tb_done >= TICKS_PER_MS) {
        tb_done += TICKS_PER_MS;
        beats++;
#if defined(SB_PROBE_SLOW)
        sb_probe_slow();
#endif
    }
    sb_beacon.beats = beats;
    sb_beacon.ticks = now;
    sb_beacon.beats_b = beats;
    sb_beacon.ticks_b = now;
    sb_beacon.seq++;

    /* Each stack's lowest word still holds the fill: nothing ran past it. */
    if (__irq_stack_top[0] != SB_STACK_FILL)
        sb_halt(SB_HALT_STACK, 1, 0);
    if (__stack_limit[0] != SB_STACK_FILL)
        sb_halt(SB_HALT_STACK, 2, 0);
}

int main(void)
{
    static const char hello[16] = "small-beeps M2 \n";

    sb_beacon.period = TICKS_PER_MS;
    if (data_probe == 0x5EED0001u && bss_probe == 0) {
        sb_beacon.marker = SB_MARKER;
        sb_console_write(hello, sizeof hello / 4);
    } else {
        sb_beacon.marker = SB_MARKER_BAD;
    }

    /* Only differences of CNT are used: its value when started, and its
     * response to writes, don't matter. */
    JL_TIMER4->CON = TIMER4_RUN;
    tb_start = JL_TIMER4->CNT;
    /* No clock register is written (HW-11, SR-2): the clock is measured. */
    sb_beacon.clock = sb_clock_measure((volatile u32 *)&JL_TIMER4->CNT);
#if defined(SB_PROBE_BIG)
    sb_probe_big();
#endif
#if defined(SB_PROBE_STACK)
    sb_probe_stack();
#endif

    sb_irq_init();
    sb_irq_enable(SRC_TIMER0, sb_tick, PRIO_TICK);
    sb_irq_enable(SRC_SPI1, lcd_spi_done, PRIO_SPI1);
    JL_TIMER0->CNT = 0;
    JL_TIMER0->PRD = TICK_PRD;
    JL_TIMER0->CON = TICK_CON;
    sb_irq_on();

#if defined(SB_TEST_FAULT)
    sb_test_fault();
#endif
#if defined(SB_TEST_STRAY)
    sb_test_stray();
#endif
#if defined(SB_TEST_BADINSN)
    sb_test_badinsn();
#endif

    /* The screen: the controller's start, the address pattern sent while
     * the display is still off, then display on (DESIGN-NOTES.md, M2). */
    lcd_init();
    screen_pattern();
    lcd_send_rows(0, SCREEN_H);
    lcd_command(LCD_DISPON, 0, 0);
    sb_beacon.screen = SB_SCREEN_PATTERN;

    if (sb_beacon.beats + 1 < TEST_SCREEN_MS)
        sb_wait_ms(TEST_SCREEN_MS - 1 - sb_beacon.beats);
    {
        u32 t = sb_now();
        screen_test();
        sb_beacon.render_ticks = sb_now() - t;
    }
    lcd_send_rows(0, SCREEN_H);
    sb_beacon.screen = SB_SCREEN_TEST;
#if defined(SB_TEST_FLOOD)
    sb_test_flood();
#endif

    /* Between ticks the core waits. Each return from the wait is one tick
     * (in steady state nothing else wakes it: the heartbeat's rows go as
     * one transfer whose end is polled), so counting them in a register
     * finds each whole second without reading anything else, and the
     * heartbeat goes on the screen then. The count reaches the beacon once
     * a second, with the ticks taken at that moment, so the test can still
     * check one wake a tick while the loop stays three instructions, as in
     * M1 (DESIGN-NOTES.md, M2). */
    {
        u32 wakes, next, b;

        lcd_wait();
        wakes = sb_beacon.wakes;
        b = sb_beacon.beats;
        sb_beacon.loop_ticks = sb_beacon.tick_count;
        while (b >= BEATS_PER_SECOND)
            b -= BEATS_PER_SECOND;
        next = wakes + BEATS_PER_SECOND - b;
        for (;;) {
            __asm__ volatile("idle");
            if (++wakes == next) {
                next += BEATS_PER_SECOND;
                sb_beacon.wakes = wakes;
                sb_beacon.wakes_ticks = sb_beacon.tick_count;
                screen_beat();
            }
        }
    }
}

