/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * Interrupts: our own vector table, which sources are enabled, and the
 * one way out when something goes wrong: report and halt.
 */

#include "sb.h"
#include "WL82.h"

/* HW-18: the handler of source n is the word at __vectors + 4n (app.ld). */
_Static_assert(sizeof(unsigned short) == 2, "a stub is 2 bytes");
extern volatile u32 __vectors[];
#define SOURCES 128

/* crt0.S: one 2-byte stub per source, in source order. */
extern const unsigned short sb_irq_stubs[];

/* HW-19 and the SDK's hwi.h (P-16): sources 0 to 2 are the debug,
 * exception and system-call sources, the CPU's own faults: their stubs
 * report a fault rather than a stray interrupt. */
#define SRC_EXCEPTION   1u
#define SRC_LAST_FAULT  2u

/* HW-20: 4 bits a source in ICFG00-ICFG31, bit 0 enable, bits 1-3 the
 * priority (higher wins). The exception source is enabled here; main
 * enables the others it handles (DESIGN-NOTES.md, M1 and M2). */
#define PRIO_FAULT  7u
#define ICFG_BITS(src, prio)  ((1u | (prio) << 1) << 4 * ((src) % 8))
#define ICFG_WORDS  32

/* HW-21: the master enable in the core register icfg. */
#define ICFG_MASTER (1u << 8)

void sb_irq_unexpected(u32 source, u32 reti) __attribute__((noreturn));

void sb_irq_init(void)
{
    volatile u32 *icfg = &q32DSP(0)->ICFG00;
    u32 n;

    for (n = 0; n < SOURCES; n++)
        __vectors[n] = (u32)&sb_irq_stubs[n];

    /* Every word written, so nothing a loader left enabled stays so. */
    _Static_assert(SRC_EXCEPTION / 8 == 0, "in ICFG00");
    icfg[0] = ICFG_BITS(SRC_EXCEPTION, PRIO_FAULT);
    for (n = 1; n < ICFG_WORDS; n++)
        icfg[n] = 0;
}

/* Installs a handler for a source and enables it at a priority (0 to 7),
 * before interrupts are turned on. */
void sb_irq_enable(u32 source, void (*handler)(void), u32 priority)
{
    volatile u32 *icfg = &q32DSP(0)->ICFG00;

    __vectors[source] = (u32)handler;
    icfg[source / 8] = (icfg[source / 8] & ~(0xFu << 4 * (source % 8))) | ICFG_BITS(source, priority);
}

/* HW-21: both gates, icfg's bit 8 and sti. */
void sb_irq_on(void)
{
    u32 cfg;

    __asm__ volatile("%0 = icfg" : "=r"(cfg));
    cfg |= ICFG_MASTER;
    __asm__ volatile("icfg = %0" :: "r"(cfg));
    __asm__ volatile("sti");
}

/* From crt0.S's stubs: an interrupt with no handler of its own. */
void sb_irq_unexpected(u32 source, u32 reti)
{
    sb_halt(source <= SRC_LAST_FAULT ? SB_HALT_FAULT : SB_HALT_STRAY, source, reti);
}

static const char reasons[3][5] = { "stray", "fault", "stack" };
static const char hex[16] = "0123456789abcdef";

/* Records why in the beacon, writes one console line, "HALT <reason>
 * <source in hex> ", and stops: interrupts off and a jump to itself,
 * which fwtest reports as a halt (docs/HARNESS.md). Nothing is resumed. */
void sb_halt(u32 reason, u32 source, u32 reti)
{
    char line[16] = "HALT ..... 000 \n";
    u32 i;

    __asm__ volatile("cli");
    sb_beacon.halt_source = source;
    sb_beacon.halt_reti = reti;
    sb_beacon.halt_reason = reason;
    for (i = 0; i < 5; i++)
        line[5 + i] = reasons[reason - 1][i];
    line[11] = hex[source >> 8 & 0xF];
    line[12] = hex[source >> 4 & 0xF];
    line[13] = hex[source & 0xF];
    sb_console_write(line, sizeof line / 4);
    for (;;)
        ;
}
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * The panel: an ST7789V-family controller on SPI1 (HW-27 to HW-32).
 * Commands go out a byte at a time; pixels go out by DMA straight from the
 * frame buffer, in chunks that SPI1's interrupt chains, so the core is
 * free while a frame is on its way (docs/DESIGN-NOTES.md, M2).
 */

#include "sb.h"
#include "WL82.h"

/* HW-29: CON bit 15 reads 1 when a transfer is done, writing bit 14
 * clears that, bit 13 makes a finished transfer raise source 16. */
#define SPI_DONE  (1u << 15)
#define SPI_CLEAR (1u << 14)
#define SPI_IRQ   (1u << 13)

/* SPI1's own set-up (clock, mode, pins) on the chip is open (Q-6, SR-3);
 * fwtest needs none (HW-29). These are the CON bits that set-up will
 * keep in every write; none yet. */
#define SPI_CON   0u

/* HW-30: PC8 low for a command byte, high for its parameters and for
 * pixels. Only that bit of the port is ever changed. */
#define LCD_DC    (1u << 8)

/* DS (HW-31, HW-32): the commands used. */
#define SWRESET   0x01u
#define SLPOUT    0x11u
#define CASET     0x2Au
#define RASET     0x2Bu
#define RAMWR     0x2Cu
#define MADCTL    0x36u
#define COLMOD    0x3Au

/* Bytes a DMA transfer sends at most: 16 rows. E-5 (HW-29) confirms
 * 480-byte transfers; how long one may be on the chip is asked in SR-3,
 * so a whole frame goes as 15 of these. */
#define ROW_BYTES (SCREEN_W * 2u)
#define CHUNK     (16u * ROW_BYTES)

/* A frame on its way: the next byte to send and how many are left, set
 * by lcd_send_rows and moved on by lcd_spi_done. */
static const u8 *volatile dma_next;
static volatile u32 dma_left;
/* 1 while a transfer started without the interrupt may still be going. */
static volatile u32 dma_polled;
static u32 frame_start;

static void dc_low(void)  { JL_PORTC->OUT &= ~LCD_DC; }
static void dc_high(void) { JL_PORTC->OUT |= LCD_DC; }

static void send_byte(u32 b)
{
    JL_SPI1->BUF = b;
    while (!(JL_SPI1->CON & SPI_DONE))
        ;
    JL_SPI1->CON = SPI_CON | SPI_CLEAR;
}

/* Waits until no transfer is on its way, so the data/command line may
 * change (HW-30: its level when a transfer starts decides it). A chained
 * frame ends in lcd_spi_done. This spins rather than idling: the last
 * chunk's interrupt could come between the test and an idle, which would
 * then sleep until the next tick (it did, once a frame, in the flood
 * test). Only a command that follows a frame still going out waits. */
void lcd_wait(void)
{
    while (dma_left)
        ;
    if (dma_polled) {
        while (dma_polled && !(JL_SPI1->CON & SPI_DONE))
            ;
        JL_SPI1->CON = SPI_CON | SPI_CLEAR;
        dma_polled = 0;
    }
}

void lcd_command(u8 command, const u8 *params, u32 count)
{
    lcd_wait();
    dc_low();
    send_byte(command);
    dc_high();
    while (count--)
        send_byte(*params++);
}

static void start_chunk(void)
{
    u32 n = dma_left < CHUNK ? dma_left : CHUNK;

    JL_SPI1->ADR = (u32)dma_next;
    dma_next += n;
    sb_beacon.chunks++;
    JL_SPI1->CNT = n;
}

/* Source 16: a chunk is done. Send the next, or end the frame. fwtest
 * also raises source 16 at the end of a transfer started with bit 13
 * clear (our experiment, P-20; HW-29 says bit 13 enables it; SR-3): with
 * no chain under way that is the polled transfer ending, so it is only
 * acknowledged, and lcd_wait sees it is over. */
void lcd_spi_done(void)
{
    u32 n = dma_left < CHUNK ? dma_left : CHUNK;

    if (!n) {
        JL_SPI1->CON = SPI_CON | SPI_CLEAR;
        dma_polled = 0;
        return;
    }
    dma_left -= n;
    if (dma_left) {
        JL_SPI1->CON = SPI_CON | SPI_CLEAR | SPI_IRQ;
        start_chunk();
    } else {
        JL_SPI1->CON = SPI_CON | SPI_CLEAR;
        sb_beacon.frame_ticks = sb_now() - frame_start;
        sb_beacon.frames++;
    }
}

/* Sends rows first to first + rows - 1 of the frame buffer to the same
 * rows of the panel (HW-31: column and row address set, then memory
 * write, high byte first; sb_fb holds each pixel that way round). Up to
 * one chunk goes as one transfer whose end is polled by the next
 * lcd_wait; more go as a chain of chunks driven by source 16. Returns
 * once the last transfer has started. */
void lcd_send_rows(u32 first, u32 rows)
{
    u32 last = first + rows - 1, bytes = rows * ROW_BYTES;
    u8 cols[4] = { 0, 0, (SCREEN_W - 1) >> 8, (SCREEN_W - 1) & 0xFF };
    u8 lines[4] = { first >> 8, first & 0xFF, last >> 8, last & 0xFF };

    frame_start = sb_now();
    lcd_command(CASET, cols, 4);
    lcd_command(RASET, lines, 4);
    lcd_command(RAMWR, 0, 0);
    dma_next = (const u8 *)&sb_fb[first * SCREEN_W];
    if (bytes <= CHUNK) {
        dma_polled = 1;
        JL_SPI1->CON = SPI_CON | SPI_CLEAR;
        JL_SPI1->ADR = (u32)dma_next;
        sb_beacon.chunks++;
        JL_SPI1->CNT = bytes;
        return;
    }
    dma_left = bytes;
    JL_SPI1->CON = SPI_CON | SPI_CLEAR | SPI_IRQ;
    start_chunk();
}

/* The controller's start: a software reset, sleep out, 16-bit pixels, and
 * the scan order. The display stays off until the first frame is in
 * (main sends DISPON). Delays from HW-32 and DS pages 163 and 184, each
 * waited on the tick, so they hold on the chip too. */
void lcd_init(void)
{
    /* DS page 215: MY = MX = MV = 0 (rows top to bottom, columns left to
     * right, not exchanged), ML = 0, RGB order (bit 3 clear), MH = 0. */
    static const u8 madctl = 0x00;
    /* DS page 224: 0x55, 65K colours and 16 bits a pixel. */
    static const u8 colmod = 0x55;

    lcd_command(SWRESET, 0, 0);
    /* 5 ms before the next command; 120 ms before sleep out when the
     * reset came in sleep mode, which it does after power-up. */
    sb_wait_ms(120);
    lcd_command(SLPOUT, 0, 0);
    sb_wait_ms(5);
    lcd_command(COLMOD, &colmod, 1);
    lcd_command(MADCTL, &madctl, 1);
}
/*
 * SPDX-License-Identifier: MIT
 * SPDX-FileCopyrightText: 2026 japes98
 *
 * What the screen shows (docs/DESIGN-NOTES.md, M2): first the address
 * pattern, in which every pixel's colour says where it is, then the test
 * screen, which shows orientation, colour order, the edges, lines, the
 * font and the heartbeat. tools/fw-suite.py checks both from fwtest's
 * captures; their layouts here and there go together.
 */

#include "sb.h"

#define BLACK   RGB565(0, 0, 0)
#define WHITE   RGB565(31, 63, 31)
#define RED     RGB565(31, 0, 0)
#define GREEN   RGB565(0, 63, 0)
#define BLUE    RGB565(0, 0, 31)
#define YELLOW  RGB565(31, 63, 0)
#define CYAN    RGB565(0, 63, 31)
#define MAGENTA RGB565(31, 0, 31)
#define GREY    RGB565(16, 32, 16)

/* The heartbeat's place: digits at scale 2 in rows BEAT_Y to
 * BEAT_Y + 15, which lcd.c sends as one transfer. */
#define BEAT_Y      200u
#define BEAT_X      96u
#define BEAT_DIGITS 5u
#define BEAT_SCALE  2u

/* The address pattern: red is x / 8 (0 to 29), green y / 4 (0 to 59),
 * blue x mod 8 times 4 plus y mod 4 (0 to 31). No two pixels share a
 * colour, so a capture shows where each pixel landed. */
void screen_pattern(void)
{
    u32 x, y;

    for (y = 0; y < SCREEN_H; y++) {
        u16 *p = &sb_fb[y * SCREEN_W];
        for (x = 0; x < SCREEN_W; x++) {
            u32 c = RGB565(x >> 3, y >> 2, (x & 7) << 2 | (y & 3));
            p[x] = (u16)(c >> 8 | (c & 0xFF) << 8);
        }
    }
}

static u8 beat_digits[BEAT_DIGITS];

static void draw_beat_digit(u32 i)
{
    gfx_glyph(BEAT_X + i * FONT_CELL * BEAT_SCALE, BEAT_Y, '0' + beat_digits[i], GREEN, BLACK, BEAT_SCALE);
}

/* The test screen:
 * - a white border on the outermost pixels of all four edges;
 * - a 12 x 12 square in each corner, 3 pixels in: red top left, green top
 *   right, blue bottom left, yellow bottom right, each named beside it;
 * - the title, and three ramps (red 32 steps, green 64, blue 32), each
 *   step one more of that channel from 0, 192 pixels wide from x = 24;
 * - a white box with its diagonals and a cross of lines;
 * - every character of the font, in three rows;
 * - the heartbeat: seconds since the start, five digits. */
void screen_test(void)
{
    static const char *const rows[3] = {
        " !\"#$%&'()*+,-./0123456789:;<=>?",
        "@ABCDEFGHIJKLMNOPQRSTUVWXYZ[\\]^_",
        "`abcdefghijklmnopqrstuvwxyz{|}~",
    };
    u32 i;

    gfx_fill(0, 0, SCREEN_W, SCREEN_H, BLACK);
    gfx_frame(0, 0, SCREEN_W, SCREEN_H, WHITE);
    gfx_fill(3, 3, 12, 12, RED);
    gfx_fill(SCREEN_W - 15, 3, 12, 12, GREEN);
    gfx_fill(3, SCREEN_H - 15, 12, 12, BLUE);
    gfx_fill(SCREEN_W - 15, SCREEN_H - 15, 12, 12, YELLOW);
    gfx_text(18, 5, "red", RED, BLACK, 1);
    gfx_text(SCREEN_W - 18 - 5 * FONT_CELL, 5, "green", GREEN, BLACK, 1);
    gfx_text(18, SCREEN_H - 13, "blue", BLUE, BLACK, 1);
    gfx_text(SCREEN_W - 18 - 6 * FONT_CELL, SCREEN_H - 13, "yellow", YELLOW, BLACK, 1);

    gfx_text(36, 20, "small-beeps M2", WHITE, BLACK, 2);
    for (i = 0; i < 32; i++) {
        gfx_fill(24 + 6 * i, 44, 6, 14, RGB565(i, 0, 0));
        gfx_fill(24 + 6 * i, 76, 6, 14, RGB565(0, 0, i));
    }
    for (i = 0; i < 64; i++)
        gfx_fill(24 + 3 * i, 60, 3, 14, RGB565(0, i, 0));

    gfx_frame(24, 96, 192, 64, WHITE);
    gfx_line(24, 96, 215, 159, CYAN);
    gfx_line(24, 159, 215, 96, MAGENTA);
    gfx_line(120, 100, 120, 155, GREY);
    gfx_line(28, 128, 211, 128, GREY);

    for (i = 0; i < 3; i++)
        gfx_text(24, 166 + 10 * i, rows[i], WHITE, BLACK, 1);

    gfx_text(24, BEAT_Y, "beat", WHITE, BLACK, BEAT_SCALE);
    for (i = 0; i < BEAT_DIGITS; i++) {
        beat_digits[i] = 0;
        draw_beat_digit(i);
    }
    sb_beacon.shown = 0;
}

/* One second more: the digits that change are drawn again, and the
 * heartbeat's rows sent (main calls this once a second). */
void screen_beat(void)
{
    u32 t = sb_now(), i = BEAT_DIGITS;

    while (i--) {
        if (++beat_digits[i] < 10) {
            draw_beat_digit(i);
            break;
        }
        beat_digits[i] = 0;
        draw_beat_digit(i);
    }
    lcd_send_rows(BEAT_Y, FONT_H * BEAT_SCALE);
    sb_beacon.shown++;
    sb_beacon.beat_ticks = sb_now() - t;
}

