    if (w > SCREEN_W - x)
        w = SCREEN_W - x;
    if (h > SCREEN_H - y)
        h = SCREEN_H - y;
    for (; h; h--, y++) {
        u16 *p = &sb_fb[y * SCREEN_W + x];
        i = w;
        if (i && ((u32)p & 2)) {
            *p++ = c;
            i--;
        }
        for (; i >= 2; i -= 2, p += 2)
            *(u32 *)p = pair;
        if (i)
            *p = c;
    }
