void gfx_frame(u32 x, u32 y, u32 w, u32 h, u32 colour)
{
    if (!w || !h)
        return;
    gfx_fill(x, y, w, 1, colour);
    gfx_fill(x, y + h - 1, w, 1, colour);
    gfx_fill(x, y, 1, h, colour);
    gfx_fill(x + w - 1, y, 1, h, colour);
