/* From (x0, y0) to (x1, y1), both ends included: each step moves one
 * pixel along the longer axis and, when the error accumulated in the
 * other axis passes half a pixel, one along that too. */
void gfx_line(int x0, int y0, int x1, int y1, u32 colour)
{
    int dx = x1 > x0 ? x1 - x0 : x0 - x1, sx = x1 > x0 ? 1 : -1;
    int dy = y1 > y0 ? y1 - y0 : y0 - y1, sy = y1 > y0 ? 1 : -1;
    int err = dx - dy;

    for (;;) {
        gfx_pixel((u32)x0, (u32)y0, colour);
        if (x0 == x1 && y0 == y1)
            return;
        if (2 * err > -dy) {
            err -= dy;
            x0 += sx;
        }
        if (2 * err < dx) {
            err += dx;
            y0 += sy;
        }
    }
}

/* One character cell, FONT_CELL x FONT_H pixels times scale, with every
 * pixel written: the glyph's in fg, the rest (the spacing column too) in
 * bg. A character outside the font draws as a filled box. The cell must
 * lie on the screen. */
void gfx_glyph(u32 x, u32 y, u32 c, u32 fg, u32 bg, u32 scale)
{
    static const u8 box[FONT_H] = { 0x1F, 0x1F, 0x1F, 0x1F, 0x1F, 0x1F, 0x1F, 0 };
    const u8 *rows = c >= FONT_FIRST && c <= FONT_LAST ? font_glyphs[c - FONT_FIRST] : box;
    u32 f = stored(fg), b = stored(bg), r, i, j, k;

    if (x + FONT_CELL * scale > SCREEN_W || y + FONT_H * scale > SCREEN_H)
        return;
    for (r = 0; r < FONT_H; r++) {
        u16 *line = &sb_fb[(y + r * scale) * SCREEN_W + x];
        u32 bits = (u32)rows[r] << 1;   /* bit FONT_CELL - 1 is the left column */
        u16 *p = line;
        for (i = FONT_CELL; i; i--) {
            u32 v = bits >> (i - 1) & 1 ? f : b;
            for (k = scale; k; k--)
                *p++ = v;
        }
        /* The other scale - 1 rows repeat this one: two pixels at a time
         * when the cell starts on a word and is an even width. */
        for (j = 1; j < scale; j++) {
            if (!((u32)line & 3) && !(FONT_CELL * scale & 1)) {
                u32 *src = (u32 *)line, *dst = (u32 *)&line[j * SCREEN_W];
                for (i = FONT_CELL * scale / 2; i; i--)
                    *dst++ = *src++;
            } else {
                for (i = 0; i < FONT_CELL * scale; i++)
                    line[j * SCREEN_W + i] = line[i];
            }
        }
    }
}

/* Text from (x, y), one cell per character, stopping at the screen's
 * right edge. Returns the x just past the last cell drawn. */
u32 gfx_text(u32 x, u32 y, const char *text, u32 fg, u32 bg, u32 scale)
{
    for (; *text && x + FONT_CELL * scale <= SCREEN_W; text++, x += FONT_CELL * scale)
        gfx_glyph(x, y, (u8)*text, fg, bg, scale);
    return x;
}

/* Measures the core clock against the 24 MHz time base (HW-13): reads
 * TIMER4's count (its address in r0, from C), runs exactly
 * SB_CLOCK_CYCLES instructions, reads it again and returns the difference. fwtest runs one instruction a cycle
 * (HW-11), so at 240 MHz the result is SB_CLOCK_CYCLES / 10, give or take
 * one for where in a count the reads fall. The two reads are far apart,
 * so fwtest never treats this as waiting (docs/HARNESS.md, "Time"). */
	.set	SB_CLOCK_LOOPS, 1200		/* 2 instructions each */

	.globl	sb_clock_measure
	.type	sb_clock_measure,@function
sb_clock_measure:
	r2 = [r0+0]
	r3 = SB_CLOCK_LOOPS
.Lspin:
	r3 += -1
	if (r3 != 0) goto .Lspin
	r1 = [r0+0]
	r0 = r1 - r2
	rts
	.size	sb_clock_measure, .-sb_clock_measure

/* One stub per interrupt source, 2 bytes each (the short form of call,
 * which reaches sb_irq_stub_common from every stub; app.ld asserts the
 * size), in source order: every
 * slot of the vector table that has no handler of its own points at its
 * source's stub (firmware/src/irq.c). A stub calls sb_irq_stub_common,
 * which works out the source from the stub's address (the return address
 * in rets) and halts with a report. Nothing returns, so clobbering rets
 * and the scratch registers is fine. */
	.p2align 1
	.globl	sb_irq_stubs, sb_irq_stubs_end
	.type	sb_irq_stubs,@function
sb_irq_stubs:
	.rept	128
	call	sb_irq_stub_common
	.endr
sb_irq_stubs_end:
	.size	sb_irq_stubs, .-sb_irq_stubs

	.type	sb_irq_stub_common,@function
sb_irq_stub_common:
	cli
	r0 = rets
	r1 = sb_irq_stubs + 2
	r0 = r0 - r1
	r0 >>= 1				/* the source number */
	r1 = reti				/* where the interrupt came in */
	call	sb_irq_unexpected
.Lnever:
	goto	.Lnever
	.size	sb_irq_stub_common, .-sb_irq_stub_common
