static u32 led_lines[8][SLOTS];
static const u32 *led_row = led_lines[0];''')
rep('''    u32 s = slot, ph = phase, base = pa_base, hbase = ph_base, pa, pb, rows, data;''','''    u32 s = slot, base = pa_base, hbase = ph_base, pa, pb, rows, data, lit;''')
rep('''    if (!s)
        phase = ph = (ph + 1) & 7;
''','''    if (!s) {
        u32 ph = (phase + 1) & 7;
        phase = ph;
        led_row = led_lines[ph];
    }
    lit = led_row[s];
''')
rep('''    JL_PORTA->OUT = base | led_pa[ph][s];
    JL_PORTH->OUT = hbase | led_ph[ph][s];''','''    JL_PORTA->OUT = base | (lit & 0xFFFFu);
    JL_PORTH->OUT = hbase | lit >> 16;''')
